// GTS302 Week 14 — Sentence Structure (Part 2) question bank.
// Fields: t = topic id, q = question, s = sentence shown in a quote box (optional),
// o = options, a = index of correct option, k = keyword/signal to look for, e = explanation.
const TYPE = ["Simple", "Compound", "Complex"];

const TOPICS = {
  cpunct: {
    name: "Compound-sentence punctuation",
    tip: "Two independent clauses need ONE of: (1) comma + FANBOYS (, and / , but / , so …), (2) a semicolon alone, or (3) semicolon + conjunctive adverb + comma (; however,). Never put a semicolon before FANBOYS (; and) and never put the comma after the conjunction (and, the …).",
  },
  logic: {
    name: "Choosing the right connector",
    tip: "Read the relationship between the two ideas first: addition → and / moreover; contrast → but / yet / nevertheless / on the other hand; result → so / therefore / as a result; choice → or / either…or; both negative → neither…nor. Then check the punctuation fits the connector type.",
  },
  splice: {
    name: "Comma splices & run-ons",
    tip: "Comma splice = two full clauses joined by a comma ONLY. Run-on = two full clauses joined with nothing (or with 'however' but no semicolon). Test: can each side stand alone as a sentence? If yes, a lone comma or nothing is wrong.",
  },
  adv: {
    name: "Adverbial clauses & subordinators",
    tip: "Learn the subordinator table by meaning — Time: when, while, before, after, until, once · Place: where, wherever, everywhere · Reason: because, since, as · Condition: if, unless, provided · Manner/comparison: as if, like, than · Contrast: although, though, even though, whereas, even if. A clause has its own subject + verb; 'after lunch' is only a phrase.",
  },
  xpunct: {
    name: "Commas in complex sentences",
    tip: "Dependent clause FIRST → comma after it (When X, Y). Independent clause first → usually NO comma (Y when X). Never put the comma right after the subordinator (Because, the …) and never use a semicolon between a dependent and an independent clause.",
  },
  rel: {
    name: "Relative clauses",
    tip: "who = person (subject), whom = person (object), whose = possession, which = thing, that = restrictive only; where/when/why = place/time/reason. Restrictive (identifies WHICH one) → no commas. Nonrestrictive (noun already identified, e.g. a name or 'my laptop') → commas on BOTH sides, and never 'that'.",
  },
  type: {
    name: "Identifying sentence type",
    tip: "Count clauses, not verbs. One subject with two verbs is still SIMPLE. Two independent clauses (joined by , FANBOYS / ; / ; however,) = COMPOUND. Any dependent clause (because, although, when, if, who, which, that…) = COMPLEX. Phrases like 'after the meeting' or 'despite being free' do not add a clause.",
  },
  concept: {
    name: "Definitions & terms",
    tip: "Compound = 2+ independent clauses. Complex = 1 independent + 1+ dependent clauses, linked by a subordinating conjunction or relative word. Relative clauses describe NOUNS. FANBOYS are coordinating conjunctions; however/therefore/moreover are conjunctive adverbs, not conjunctions.",
  },
};

